import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.CpLciM8b.js";const f=JSON.parse('{"title":"Flaky scoring","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/flaky-scoring.md","filePath":"concepts/flaky-scoring.md","lastUpdated":1785946507000}'),n={name:"concepts/flaky-scoring.md"};function r(i,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="flaky-scoring" tabindex="-1">Flaky scoring <a class="header-anchor" href="#flaky-scoring" aria-label="Permalink to &quot;Flaky scoring&quot;">​</a></h1><p>Most teams &quot;detect&quot; flakes by eyeballing <code>retries &gt; 0</code>. That is noisy in both directions — it flags a test that failed once for a real reason, and misses a test that fails one run in twenty. Flakemetry replaces the eyeball with a transparent statistical model that ships its reasoning alongside every score.</p><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><p>The flaky score is a <strong>Beta-Binomial</strong> estimate of a test&#39;s failure-inconsistency rate, with <strong>exponential time-decay</strong> so recent behaviour counts for more than last month&#39;s. A Bayesian prior means a test does not swing to &quot;extremely flaky&quot; on a single red run; it needs enough samples before the score becomes confident. That is why a brand-new test with one failure does not top the board.</p><h2 id="the-strongest-signal-same-commit-different-result" tabindex="-1">The strongest signal: same commit, different result <a class="header-anchor" href="#the-strongest-signal-same-commit-different-result" aria-label="Permalink to &quot;The strongest signal: same commit, different result&quot;">​</a></h2><p>The single most powerful evidence of flakiness is <strong>same commit, different result</strong> — the code did not change but the outcome did. A deterministic failure repeats on the same commit; a flaky one does not. The model weighs this signal heavily because it isolates non-determinism from genuine regressions.</p><h2 id="reason-codes" tabindex="-1">Reason codes <a class="header-anchor" href="#reason-codes" aria-label="Permalink to &quot;Reason codes&quot;">​</a></h2><p>Every score is explainable. It ships with <strong>reason codes</strong> — the human-readable evidence behind the number:</p><ul><li><strong>same commit, different result</strong> — flip-flopped outcomes with no code change.</li><li><strong>pass-on-rerun</strong> — failed, then passed on retry with no code change.</li><li><strong>intermittent across branches</strong> — fails on some branches and not others for no code reason.</li></ul><p>Because the reasons travel with the score, you can trust it or challenge it — you are never handed a black-box number.</p><h2 id="scoring-policy" tabindex="-1">Scoring policy <a class="header-anchor" href="#scoring-policy" aria-label="Permalink to &quot;Scoring policy&quot;">​</a></h2><p>The threshold at which a test is considered flaky, and the minimum number of samples before a score is surfaced, are configurable per project (and instance-wide). See the <a href="/flakemetry/v/2026-09-30/reference/configuration">Configuration reference</a> for the knobs, and <a href="/flakemetry/v/2026-09-30/guide/github-action">auto-quarantine</a> for how a high score can automatically stop a test from failing the build.</p><p>You can overrule it. Quarantining or releasing a test by hand — from the test page, or with <a href="/flakemetry/v/2026-09-30/guide/cli"><code>flakemetry quarantine</code></a> — takes that test out of the scorer&#39;s hands until you give it back. A decision the next run silently reverses would be worse than no control at all, so the automation steps aside rather than arguing.</p><p>The full model is documented in the <a href="https://github.com/AKogut/flakemetry/wiki/Flaky-Scoring" target="_blank" rel="noreferrer">Flaky Scoring wiki page</a>.</p>',14)])])}const u=t(n,[["render",r]]);export{f as __pageData,u as default};
